<template><view class="timeline"><view class="section-title"><text class="section-title__eyebrow">{{ content.historyEyebrow }}</text><text class="section-title__main">{{ content.historyTitle }}</text></view><view v-if="items.length"><view v-for="item in items" :key="item.id" class="timeline__item"><view class="timeline__year">{{ item.year }}</view><view class="timeline__dot" /><view class="timeline__content"><image v-if="item.image" class="timeline__image" :src="item.image" mode="aspectFill" /><text class="timeline__title">{{ item.title }}</text><text class="timeline__copy">{{ item.content }}</text></view></view></view><view v-else class="timeline__empty">暂无品牌历程</view></view></template>
<script setup>import { computed } from 'vue'; const props = defineProps({ content: { type: Object, required: true } }); const items = computed(() => (props.content.history || []).filter((item) => item.enabled).sort((a, b) => a.sort - b.sort))</script>
<style scoped lang="scss">.timeline{padding:58rpx 30rpx 54rpx;background:#f7f3ed}.section-title{margin-bottom:42rpx;text-align:center}.section-title__eyebrow,.section-title__main{display:block}.section-title__eyebrow{color:#9b7644;font-size:20rpx}.section-title__main{margin-top:10rpx;color:#153c34;font-family:"STKaiti",serif;font-size:46rpx;font-weight:700}.timeline__item{display:grid;grid-template-columns:100rpx 30rpx 1fr;min-height:174rpx}.timeline__year{color:#a67d43;font-size:28rpx;font-weight:700}.timeline__dot{position:relative;width:18rpx;height:18rpx;margin-top:10rpx;border:5rpx solid #f7f3ed;border-radius:50%;background:#a67d43;box-shadow:0 0 0 2rpx #a67d43}.timeline__dot::after{position:absolute;top:22rpx;left:6rpx;width:2rpx;height:135rpx;background:#d9c6a6;content:''}.timeline__item:last-child .timeline__dot::after{display:none}.timeline__image{width:100%;height:160rpx;margin-bottom:14rpx}.timeline__title{display:block;color:#163d35;font-size:30rpx;font-weight:700}.timeline__copy{display:block;margin-top:10rpx;color:#686f6c;font-size:24rpx;line-height:40rpx}.timeline__empty{padding:34rpx;color:#929a96;font-size:25rpx;text-align:center}</style>
